571	    /// Updates the collaboration mode with new model and/or effort values.
572	    ///
573	    /// - `model`: `Some(s)` to update the model, `None` to keep the current model
574	    /// - `effort`: `Some(Some(e))` to set effort to `e`, `Some(None)` to clear effort, `None` to keep current effort
575	    /// - `developer_instructions`: `Some(Some(s))` to set instructions, `Some(None)` to clear them, `None` to keep current
576	    ///
577	    /// Returns a new `CollaborationMode` with updated values, preserving the mode.
578	    pub fn with_updates(
579	        &self,
580	        model: Option<String>,
581	        effort: Option<Option<ReasoningEffort>>,
582	        developer_instructions: Option<Option<String>>,
583	    ) -> Self {
584	        let settings = self.settings_ref();
585	        let updated_settings = Settings {
586	            model: model.unwrap_or_else(|| settings.model.clone()),
587	            reasoning_effort: effort.unwrap_or(settings.reasoning_effort),
588	            developer_instructions: developer_instructions
589	                .unwrap_or_else(|| settings.developer_instructions.clone()),
590	        };
591	
592	        CollaborationMode {
593	            mode: self.mode,
594	            settings: updated_settings,
595	        }
596	    }
