598	    /// Applies a mask to this collaboration mode, returning a new collaboration mode
599	    /// with the mask values applied. Fields in the mask that are `Some` will override
600	    /// the corresponding fields, while `None` values will preserve the original values.
601	    ///
602	    /// The `name` field in the mask is ignored as it's metadata for the mask itself.
603	    pub fn apply_mask(&self, mask: &CollaborationModeMask) -> Self {
604	        let settings = self.settings_ref();
605	        CollaborationMode {
606	            mode: mask.mode.unwrap_or(self.mode),
607	            settings: Settings {
608	                model: mask.model.clone().unwrap_or_else(|| settings.model.clone()),
609	                reasoning_effort: mask.reasoning_effort.unwrap_or(settings.reasoning_effort),
610	                developer_instructions: mask
611	                    .developer_instructions
612	                    .clone()
613	                    .unwrap_or_else(|| settings.developer_instructions.clone()),
614	            },
615	        }
